def lis(a):
    """Length of the longest strictly increasing subsequence."""
    if not a:
        return 0
    best = cur = 1
    for i in range(1, len(a)):
        cur = cur + 1 if a[i] > a[i - 1] else 1
        best = max(best, cur)
    return best

